from build import S,lesson as L


def lessons():
 return [
 L('assets','Models, tokenizers, and task heads','A checkpoint identifies compatible configuration, vocabulary/tokenizer rules, and weights. Auto classes choose implementations from metadata. A base model produces representations; task-specific heads produce task outputs. Examples name local fixtures and never require a model download.',
 S('# Assume local-checkpoint contains compatible saved assets.\ntokenizer=AutoTokenizer.~from_pretrained~("local-checkpoint",local_files_only=True)','Loads the tokenizer from local assets','Trains a tokenizer from scratch|Loads model weights only','The tokenizer loader restores text-processing assets, distinct from a model.','from_config|save_pretrained','What is loaded?'),
 S('# Assume cfg is a valid architecture configuration.\nmodel=AutoModel.~from_config~(cfg)','Constructs a model with newly initialized weights','Loads pretrained weights automatically|Tokenizes a document','Configuration describes architecture but does not itself contain pretrained parameters.','from_pretrained|save_pretrained','What weights should a reviewer expect?'),
 S('# Assume checkpoint supports causal generation.\nmodel=~AutoModelForCausalLM~.from_pretrained("local-checkpoint",local_files_only=True)','Loads a model with a causal-language-model head','Loads only a tokenizer|Loads only a sentence classifier','The task-specific Auto class selects the causal LM output contract.','AutoTokenizer|AutoModelForSequenceClassification','What task contract is requested?'),
 S('# Assume a compatible sequence-classification checkpoint.\nmodel=~AutoModelForSequenceClassification~.from_pretrained("local-checkpoint",local_files_only=True)','Loads a sequence-classification head','Loads a text-to-image pipeline|Loads a tokenizer only','A sequence classifier predicts a label distribution for each input sequence.','AutoTokenizer|AutoModelForCausalLM','What head does this loader request?')),
 L('tokenization','Tokenization and explicit input contracts','Tokenizer calls return model-input mappings, usually including input_ids and attention_mask. Token IDs depend on the tokenizer vocabulary and are not word counts. Explicit fixtures are provided whenever an exercise asks for exact IDs or lengths.',
 S('# Assume tokenizer is compatible with the chosen model.\nbatch=tokenizer("${word}",return_tensors=~"pt"~)','Returns tensor-valued inputs for PyTorch','Returns decoded strings only|Runs the model forward pass','The return_tensors setting selects the tensor framework.','"np"|None','What representation is requested?'),
 S('batch={"input_ids":[[${n},${m}]],"attention_mask":[[1,1]]}\nprint(batch[~"input_ids"~][0])','[${n}, ${m}]','[1, 1]|KeyError','input_ids holds vocabulary IDs; the mask has a separate purpose.','"attention_mask"|"labels"'),
 S('batch={"input_ids":[[${n},${m},0]],"attention_mask":[[1,1,0]]}\nprint(sum(batch[~"attention_mask"~][0]))','2','3|${add}','In this fixture, ones identify the two non-padding positions.','"input_ids"|"labels"'),
 S('# tokenizer is a configured text tokenizer.\nencoded=tokenizer("${word}",~add_special_tokens=False~)','Does not automatically add special tokens in this call','Removes all punctuation|Guarantees one token per word','This flag controls added structural tokens, not vocabulary segmentation.','add_special_tokens=True|return_attention_mask=False','What tokenization behavior changes?')),
 L('padding','Padding, truncation, and batch length','Padding aligns sequence lengths; truncation limits long sequences. padding=True pads to the longest sequence in the batch, not necessarily max_length. padding="max_length" requests a fixed padded width. A valid pad token is required for tokenizers that do not define one.',
 S('# Assume tokenizer has a pad token.\nbatch=tokenizer(texts,padding=~True~,return_tensors="pt")','Pads to the longest sequence in this batch','Always pads to model maximum length|Removes all long sequences','True selects longest-in-batch padding.','"max_length"|False','How is padding width chosen?'),
 S('# Assume the tokenizer supports these lengths and has a pad token.\nbatch=tokenizer(texts,padding="max_length",truncation=True,max_length=~${n}~,return_tensors="pt")','Requests padded/truncated sequences of length ${n}','Adds exactly ${n} new generated tokens|Creates ${n} documents','With fixed-length padding and truncation, max_length sets encoded sequence width.','${next}|${m}','What length contract is requested?'),
 S('lengths=[2,4]\n# Fixture: pad both sequences to the longest encoded length.\nwidth=~max(lengths)~\nprint(width)','4','2|6','Longest-in-batch padding selects the maximum encoded length.','min(lengths)|sum(lengths)'),
 S('# Assume tokenizer has a pad token.\nbatch=tokenizer(texts,truncation=~True~,max_length=${n})','Limits encoded length according to the truncation strategy','Guarantees fixed-width padding|Generates new tokens','Truncation controls shortening; padding must be requested separately.','False|None','What does this option enable?')),
 L('batches','Batch dictionaries and model arguments','**batch expands mapping entries into keyword arguments. The model expects compatible names, integer token IDs, and correctly shaped masks. Batch dimension comes first for common text models. Keep tensor device placement aligned with a single-device model.',
 S('batch={"input_ids":[[${n},${m}]]}\ndef model(*,input_ids): return len(input_ids)\nprint(model(~**batch~))','1','2|TypeError','The explicit stub demonstrates dictionary-to-keyword expansion used by model calls.','batch|*batch'),
 S('batch={"input_ids":[[${n},0],[${m},0]],"attention_mask":[[1,0],[1,0]]}\nprint(~len(batch["input_ids"])~)','2','1|4','The outer dimension counts input sequences.','len(batch)|sum(batch["attention_mask"][0])'),
 S('# Assume batch is a tensor-valued BatchEncoding and model uses one device.\nbatch=batch.~to~(model.device)','Moves batch tensors to the model device','Changes every token ID to floating point|Loads another model','BatchEncoding.to forwards device placement to its tensor values.','decode|save_pretrained','What does this operation change?'),
 S('# Assume model accepts input_ids and attention_mask.\noutputs=model(input_ids=ids,~attention_mask=mask~)','Supplies the explicit attention mask','Requests output probabilities|Sets the training labels','The argument names the valid-attention input separately from labels and IDs.','labels=mask|output_attentions=True','What is being passed?')),
 L('outputs','ModelOutput objects and task-dependent shapes','Outputs expose named fields whose presence depends on the model and requested options. Sequence classification logits commonly have shape batch-by-labels; causal LM logits are batch-by-sequence-by-vocabulary. Raw logits are not normalized probabilities. Avoid relying on positional tuple indices when optional fields can change.',
 S('from types import SimpleNamespace\noutputs=SimpleNamespace(logits=[[0,${n}]])\nprint(outputs.~logits~[0][1])','${n}','0|AttributeError','This explicit output fixture demonstrates named-field access.','loss|hidden_states'),
 S('# Sequence-classification fixture: two examples, three labels.\nshape=(2,3)\nprint(~shape[-1]~)','3','2|(2, 3)','The final dimension indexes labels for this task head.','shape[0]|shape'),
 S('# Causal-LM fixture: batch=2, sequence=4, vocabulary=100.\nshape=(2,4,100)\nprint(~shape[1]~)','4','2|100','The middle dimension contains per-position predictions.','shape[0]|shape[2]'),
 S('# Assume classification outputs have logits shaped (batch, labels).\nprobabilities=outputs.logits.~softmax(dim=-1)~','Normalizes scores across labels for each example','Normalizes across examples|Changes the model to evaluation mode','The final axis is the label axis for the stated task.','softmax(dim=0)|detach()','What does this postprocessing do?')),
 L('inference','Evaluation mode and bounded inference contexts','Model mode and autograd policy are separate. eval sets inference behavior for training-sensitive modules. inference_mode suppresses autograd overhead with additional restrictions. Inputs and outputs may occupy substantial device memory even without gradients.',
 S('# model is a PyTorch-backed Transformers model.\nmodel.~eval()~','Switches training-sensitive modules to evaluation behavior','Disables all gradient recording globally|Moves weights to CPU','eval changes module behavior; it is not a gradient context manager.','train()|zero_grad()','What changes?'),
 S('# Assume compatible model and tensor batch.\nwith torch.~inference_mode~():\n    outputs=model(**batch)','Runs this forward pass without recording an autograd graph','Trains the model automatically|Guarantees sampling is deterministic','The context controls autograd behavior, not a model generation strategy.','enable_grad|manual_seed','What execution contract is selected?'),
 S('# Given an output tensor on a single-device model:\nsnapshot=outputs.logits.~detach().cpu()~','Produces an untracked CPU view or copy of the scores','Converts logits into probabilities|Updates model parameters','detach removes graph linkage and cpu moves data when needed.','softmax(dim=-1)|argmax(dim=-1)','What transformation is requested?'),
 S('# Assume a normal PyTorch-backed model in eval mode.\nmodel.eval()\nwith torch.~enable_grad~():\n    outputs=model(**batch)','Gradients can still be recorded for tracked parameters','eval makes gradient recording impossible|The model is switched to training mode','Evaluation mode and gradient recording are independent settings.','no_grad|inference_mode','What is true of the forward pass?')),
 L('generation','Generation budgets and stopping','generate performs iterative decoding rather than a single forward call. max_new_tokens bounds newly generated tokens; max_length includes the input length for decoder-only generation. EOS can stop earlier. Generated content is model-dependent, so exercises test API contracts instead of guessing text.',
 S('generated=model.generate(**batch,max_new_tokens=~${n}~)','Generates at most ${n} new tokens per sequence','Always generates exactly ${n} words|Sets batch size to ${n}','The budget counts tokens after the prompt; EOS can end generation earlier.','${next}|${m}','What budget is set?'),
 S('generated=model.generate(**batch,do_sample=~False~,num_beams=1)','Requests greedy decoding under ordinary generation settings','Requests random sampling|Always uses beam search with multiple beams','With one beam and sampling disabled, ordinary decoding chooses a highest-scoring next token.','True|None','What decoding policy is requested?'),
 S('generated=model.generate(**batch,do_sample=~True~,temperature=0.7)','Enables sampling with temperature scaling','Guarantees the same text on every run|Limits output to seven tokens','Temperature affects the sampling distribution when sampling is enabled.','False|None','What behavior is enabled?'),
 S('generated=model.generate(**batch,~num_beams=4~,do_sample=False)','Requests beam search with four beams','Requests a batch of four inputs|Creates four independent models','num_beams controls decoding search width, not input batch size.','num_beams=1|num_return_sequences=4','What does this option control?')),
 L('decoding','Separating prompt tokens from continuations','Decoder-only generate normally returns the prompt prefix plus continuation. Slice by encoded input width before decoding new tokens. This contract differs from encoder-decoder generation. decode handles one sequence and batch_decode handles multiple sequences; special-token skipping changes presentation.',
 S('# Decoder-only fixture: prompt is the first two IDs.\nids=[${n},${m},7,8]\nprint(ids[~2:~])','[7, 8]','[${n}, ${m}]|[${n}, ${m}, 7, 8]','Slicing at prompt width keeps only the continuation.',':2|:'),
 S('# Assume decoder-only generated is (batch, prompt+new).\nnew_ids=generated[:,~batch["input_ids"].shape[1]:~]','Removes the encoded prompt-width prefix','Keeps only the prompt|Removes the first batch example','The second dimension is token position for this fixture.',':batch["input_ids"].shape[1]|0:1','What does this slice select?'),
 S('text=tokenizer.decode(ids,~skip_special_tokens=True~)','Omits registered special tokens from decoded text','Removes every punctuation token|Drops the prompt automatically','The option affects special-token presentation, not prompt slicing.','skip_special_tokens=False|clean_up_tokenization_spaces=False','What cleanup is requested?'),
 S('texts=tokenizer.~batch_decode~(generated,skip_special_tokens=True)','Decodes each generated sequence into a string','Returns logits for each sequence|Trains the tokenizer','batch_decode handles a batch, unlike a single-sequence decode call.','encode|tokenize','What does this operation produce?')),
 L('chat','Chat templates and model-specific formatting','Chat messages use role/content fields, but models consume token sequences. apply_chat_template uses the tokenizer checkpoint formatting. Some templates add a generation prompt and some ignore that flag. Avoid duplicating special tokens when formatting to text before tokenizing.',
 S('messages=[{"role":"user","content":"${word}"}]\nprint(messages[0][~"content"~])','${word}','user|KeyError','The message content is separate from its speaker role.','"role"|"text"'),
 S('formatted=tokenizer.~apply_chat_template~(messages,tokenize=False)','Formats messages using the tokenizer chat template','Always returns a PyTorch tensor|Generates an assistant reply','With tokenize=False the operation creates formatted text, not model output.','batch_decode|save_pretrained','What does this call do?'),
 S('formatted=tokenizer.apply_chat_template(messages,tokenize=False)\nbatch=tokenizer(formatted,~add_special_tokens=False~,return_tensors="pt")','Avoids adding another layer of special tokens','Disables all attention masks|Removes model weights','A chat template normally supplies its own structural tokens; later tokenization should not duplicate them.','add_special_tokens=True|return_attention_mask=False','Why use this option?'),
 S('ids=tokenizer.apply_chat_template(messages,tokenize=True,~add_generation_prompt=True~)','Requests an assistant-turn prompt where the template supports it','Always appends the same universal token|Generates the reply immediately','Generation-prompt behavior belongs to the specific template, not a universal chat encoding.','add_generation_prompt=False|continue_final_message=True','What is requested?')),
 L('labels','Labels, ignored positions, and collators','Training input labels depend on the task. Common PyTorch loss paths ignore label -100; an attention mask and ignored labels serve different purposes. DataCollatorWithPadding batches and pads examples at runtime. Read actual label alignment rather than assuming every task shifts in the same place.',
 S('labels=[${n},${m},-100]\nprint(sum(x~!=-100~ for x in labels))','2','3|1','Two target positions remain eligible for a loss that ignores -100.','==-100|>100'),
 S('# Assume a standard causal LM handles label shifting internally.\noutputs=model(input_ids=ids,attention_mask=mask,~labels=labels~)','Requests a training loss using target labels','Changes the tokenizer vocabulary|Requests only generated text','Passing labels enables the task head loss path; masking labels remains the caller/collator responsibility.','output_hidden_states=True|use_cache=True','What additional output can this enable?'),
 S('collator=~DataCollatorWithPadding~(tokenizer=tokenizer)\nbatch=collator(features)','Pads the provided examples into a batch','Always masks random tokens for MLM|Trains a model','This collator handles padding, not the distinct masked-language-model corruption task.','DataCollatorForLanguageModeling|AutoTokenizer','What is the batching role?'),
 S('attention_mask=[1,1,0]\nlabels=[${n},${m},0]\nlabels=[token if keep else ~-100~ for token,keep in zip(labels,attention_mask)]\nprint(labels)','[${n}, ${m}, -100]','[${n}, ${m}, 0]|[-100, -100, -100]','This explicit fixture excludes padding from a loss whose ignore index is -100.','0|-1')),
 L('persistence','Saving assets and reproducible loading','Save both model and tokenizer assets for a reusable checkpoint. A revision can pin a model repository snapshot. local_files_only prevents fetching missing remote assets. A cache directory is not the same as an explicit exported checkpoint. Remote custom code requires separate deliberate review.',
 S('model.~save_pretrained~("export")\ntokenizer.save_pretrained("export")','Saves model and tokenizer assets into export','Only writes a Python pickle of one object|Uploads automatically to the Hub','The two calls preserve compatible model and preprocessing assets for later loading.','push_to_hub|from_pretrained','What is saved locally?'),
 S('model=AutoModel.from_pretrained("local-checkpoint",~local_files_only=True~)','Uses local assets and fails if required files are unavailable','Downloads missing files automatically|Guarantees the model is small','This option prevents resolving missing assets through a download.','local_files_only=False|force_download=True','What loading constraint applies?'),
 S('# Assume commit is a full model-repository commit identifier.\nmodel=AutoModel.from_pretrained(checkpoint,~revision=commit~)','Pins the requested asset revision','Fixes every random seed|Selects the training learning rate','A repository revision fixes which files are resolved, not all runtime behavior.','cache_dir=commit|subfolder=commit','What does revision control?'),
 S('tokenizer=AutoTokenizer.from_pretrained(checkpoint,~trust_remote_code=False~)','Does not opt into executing repository-supplied custom code','Proves all assets harmless|Runs custom code in a secure sandbox','The flag controls custom code opt-in; it is not a general sandbox or provenance guarantee.','trust_remote_code=True|local_files_only=False','What boundary does this flag enforce?')),
 L('debugging','Diagnosing integration mistakes','Check tokenizer/model compatibility, tensor shape and dtype, device placement, and generation return type before blaming model quality. Additional hidden states, attention tensors, or generation scores can consume substantial memory. Optional outputs should be requested only when they serve the task.',
 S('# Assume config has id2label={0:"negative",1:"positive"}.\nconfig={0:"negative",1:"positive"}\nprediction=1\nprint(config[~prediction~])','positive','negative|KeyError','Class IDs need the matching checkpoint label mapping for interpretation.','0|2'),
 S('outputs=model(**batch,~output_hidden_states=True~)','Requests hidden-state outputs where supported','Guarantees lower memory use|Changes tokenizer padding','Extra intermediate tensors can increase retained output memory.','output_hidden_states=False|return_dict=False','What extra data is requested?'),
 S('result=model.generate(**batch,~return_dict_in_generate=True~,output_scores=True)','Requests structured generation outputs including available scores','Returns only decoded strings|Converts scores to probabilities automatically','Structured output exposes fields such as sequences; scores remain model/generation outputs requiring interpretation.','return_dict_in_generate=False|output_attentions=False','What return contract is selected?'),
 S('from types import SimpleNamespace\nresult=SimpleNamespace(sequences=[[${n},7,8]],scores=())\nprint(result.~sequences~[0][-1])','8','${n}|AttributeError','Read token sequences from the named field in this explicit structured-output fixture.','scores|logits')),
 ]
